revoke all on public.program_holder_students, public.payout_schedules, public.enrollment_funding_records from anon;
create policy student_finance_admin_read on public.program_holder_students as restrictive for select to authenticated using (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin','staff','org_admin')));
create policy student_payout_admin_read on public.payout_schedules as restrictive for select to authenticated using (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin','staff','org_admin')));
create policy funding_evidence_admin_only on public.enrollment_funding_records as restrictive for all to authenticated using (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin','staff','workforce_board'))) with check (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in ('admin','super_admin','staff','workforce_board')));
